widget.solution:
def within_tolerance(ours, theirs, se, k=2):
    return abs(ours - theirs) <= k * se

def matches(table_ours, table_theirs, se_table, k=2):
    hits = 0
    for cell in table_theirs:
        # only the cells the paper reports
        if within_tolerance(table_ours[cell], table_theirs[cell], se_table[cell], k):
            hits += 1
    return hits / len(table_theirs)
